    # test standing_still_stays_put (hop/tests/moves.slg:11)
    def self.standing_still_stays_put
      Hop::World.start(1)
      Spec::Ranges.list((1..30)).each do |i|
        Hop::World.step(Hop::Tests::Moves.rest)
      end
      Spec.assert(Hop::World.player.at == Hop::Geom::Vec3.new(x: 0, y: 0, z: 0))
      Spec.assert(Hop::World.player.grounded)
      Spec.assert(Hop::World.ticks == 30)
    end
    SUITE.test("hop.tests.moves.standing_still_stays_put", method(:standing_still_stays_put))

    # test running_reaches_full_speed (hop/tests/moves.slg:19)
    # @why the first tick starts in the air, so it gains 1; then 2 a tick up to 16
    def self.running_reaches_full_speed
      Hop::World.start(1)
      Spec::Ranges.list((1..10)).each do |i|
        Hop::World.step(Hop::Tests::Moves.right)
      end
      Spec.assert(Hop::World.player.vel.x == 16)
      Spec.assert(Hop::World.player.at.x == 96)
      Spec.assert(Hop::World.player.yaw == 0)
    end
    SUITE.test("hop.tests.moves.running_reaches_full_speed", method(:running_reaches_full_speed))

    # test a_held_jump_peaks_at_380 (hop/tests/moves.slg:28)
    # @why a held jump rises 38 + 36 + ... + 2 = 380 sub-metres
    def self.a_held_jump_peaks_at_380
      Hop::World.start(1)
      Hop::World.step(Hop::Tests::Moves.rest)
      top = 0
      Spec::Ranges.list((1..50)).each do |i|
        Hop::World.step(Hop::Tests::Moves.jump)
        top = [top, Hop::World.player.at.y].max
      end
      Spec.assert(top == 380)
      Spec.assert(Hop::World.player.grounded)
    end
    SUITE.test("hop.tests.moves.a_held_jump_peaks_at_380", method(:a_held_jump_peaks_at_380))

    # test a_short_hop_peaks_at_94 (hop/tests/moves.slg:41)
    # @why let go after one tick: 38, then cut to 16 and fall away: 14 + 12 + ... + 2 more
    def self.a_short_hop_peaks_at_94
      Hop::World.start(1)
      Hop::World.step(Hop::Tests::Moves.rest)
      Hop::World.step(Hop::Tests::Moves.jump)
      top = 0
      Spec::Ranges.list((1..30)).each do |i|
        Hop::World.step(Hop::Tests::Moves.rest)
        top = [top, Hop::World.player.at.y].max
      end
      Spec.assert(top == 94)
    end
    SUITE.test("hop.tests.moves.a_short_hop_peaks_at_94", method(:a_short_hop_peaks_at_94))

